if (board === 'zan') { var p4 = findPanel(doc, '热赞排行'); return p4 ? mediaCards(p4) : new org.jsoup.select.Elements(); }
if (board === 'hot') {
var out = new org.jsoup.select.Elements();
var ph = findPanel(doc, '网友热搜');
if (ph) {
var lis = ph.select('li');
for (var i = 0; i < lis.size(); i++) {
