if (!name || !u) continue;
var lt = String(lis.get(i).text());
var ma = lt.match(/[(（]([^)）]+)[)）]/);
out.add(mkCard(name, ma ? ma[1] : '', '', '', '', coverOf(u), u, ''));
}
}
return out;
}
if (board === 'update') {
var out2 = new org.jsoup.select.Elements();
var pu = findPanel(doc, '今日更新');
if (pu) {
var rows = pu.select('tr');
for (var j = 0; j < rows.size(); j++) {
var tr = rows.get(j);
var a2 = tr.select('td a[href*="/ciwei/"]').first();
if (!a2) continue;
var name2 = String(a2.text()).replace(/\s+/g, ' ').trim();
var u2 = String(a2.attr('abs:href') || a2.attr('href') || '');
if (!name2 || !u2) continue;
var kind = '';
var ka = tr.select('td.book_author a[href*="ciwei"]').first();
if (ka) kind = String(ka.text()).trim();
var lc = '';
var la = tr.select('td.index-chapter a').first();
if (la) lc = String(la.text()).replace(/\s+/g, ' ').trim();
var author2 = '';
var aua = tr.select('td.book_author a:not([href])').first();
if (aua) author2 = String(aua.text()).trim();
if (!author2) {
var aut = tr.select('td.book_author');
for (var q = 0; q < aut.size(); q++) {
var at = String(aut.get(q).text()).trim();
if (at && at !== kind && at.charAt(0) !== '[') author2 = at;
}
}
var upd2 = '';
var upe = tr.select('td.book_update').first();
if (upe) upd2 = String(upe.text()).trim();
out2.add(mkCard(name2, author2, kind, lc, '', coverOf(u2), u2, upd2));
}
}
return out2;
}
return mediaCards(doc);
})()

